AS
BEGIN
    DECLARE @minValidVersion BigInt 
    DECLARE @sync_last_received_anchor_varbinary varbinary(8)

    DECLARE @wasDeleted int

    SET @sync_last_received_anchor_varbinary = CONVERT(varbinary(8), @sync_last_received_anchor);

    SET @wasDeleted = 0
    
    IF EXISTS (SELECT 1 FROM [track].[tblTransactions] CT
                        WHERE CT.PK_TransactionGuid = @TransactionGuid
                                AND (CT.DeletedRowVersion IS NOT NULL))
    BEGIN
        SET @wasDeleted = 1
    END

    IF (@wasDeleted = 0)
    BEGIN
        ;   WITH existingData AS (
                SELECT [dbo].[tblTransactions].[TransID],[dbo].[tblTransactions].[AliasName],[dbo].[tblTransactions].[SubType],[dbo].[tblTransactions].[Site],[dbo].[tblTransactions].[TransReferenceID],[dbo].[tblTransactions].[InventoryDate],[dbo].[tblTransactions].[ShipToID],[dbo].[tblTransactions].[ShipToCode],[dbo].[tblTransactions].[SupplierID],[dbo].[tblTransactions].[SupplierCode],[dbo].[tblTransactions].[CreatedDate],[dbo].[tblTransactions].[CreatedBy],[dbo].[tblTransactions].[RequestedDeliveryDate],[dbo].[tblTransactions].[UpdatedDate],[dbo].[tblTransactions].[UpdatedBy],[dbo].[tblTransactions].[TransDateTime],[dbo].[tblTransactions].[TransVersion],[dbo].[tblTransactions].[SCACCode],[dbo].[tblTransactions].[CardNumber],[dbo].[tblTransactions].[ShipmentNumber],[dbo].[tblTransactions].[ShipperID],[dbo].[tblTransactions].[ShipperCode],[dbo].[tblTransactions].[OwnerID],[dbo].[tblTransactions].[OwnerCode],[dbo].[tblTransactions].[ManagerID],[dbo].[tblTransactions].[ManagerCode],[dbo].[tblTransactions].[CarrierID],[dbo].[tblTransactions].[CarrierCode],[dbo].[tblTransactions].[ConjoinTransID],[dbo].[tblTransactions].[ReversedTransID],[dbo].[tblTransactions].[LinkedDocumentNumber],[dbo].[tblTransactions].[ReversalType],[dbo].[tblTransactions].[PONumber],[dbo].[tblTransactions].[TimeIn],[dbo].[tblTransactions].[TimeOut],[dbo].[tblTransactions].[TimeEnd],[dbo].[tblTransactions].[RoutingID],[dbo].[tblTransactions].[TicketSource],[dbo].[tblTransactions].[LoadID],[dbo].[tblTransactions].[BillToID],[dbo].[tblTransactions].[BillToCode],[dbo].[tblTransactions].[DriverIdentificationNumber],[dbo].[tblTransactions].[CreditAmount],[dbo].[tblTransactions].[CardExpiration],[dbo].[tblTransactions].[CardName],[dbo].[tblTransactions].[CardType],[dbo].[tblTransactions].[CashAmount],[dbo].[tblTransactions].[RouteOriginationDate],[dbo].[tblTransactions].[InternationalRouteIndicator],[dbo].[tblTransactions].[PreviousRoutingID],[dbo].[tblTransactions].[ShippingDocumentNumber],[dbo].[tblTr