ansactions].[ShipperCompanyGuid],[dbo].[tblTransactions].[ShipToCompanyGuid],[dbo].[tblTransactions].[Source1EquipmentGuid],[dbo].[tblTransactions].[Source2EquipmentGuid],[dbo].[tblTransactions].[Source3EquipmentGuid],[dbo].[tblTransactions].[SupplierCompanyGuid],[dbo].[tblTransactions].[CarrierCompanyGuid],[dbo].[tblTransactions].[ReasonCodeGuid],[dbo].[tblTransactions].[OriginStationIATAID],[dbo].[tblTransactions].[PreviousStationIATAID],[dbo].[tblTransactions].[NextStationIATAID],[dbo].[tblTransactions].[FinalStationIATAID],[dbo].[tblTransactions].[OperatorName],[dbo].[tblTransactions].[FuelAdditiveFlag],[dbo].[tblTransactions].[IssuePoint],[dbo].[tblTransactions].[IssuePointNumber],[dbo].[tblTransactions].[RadioNumber],[dbo].[tblTransactions].[GateID],[dbo].[tblTransactions].[GateGuid],[dbo].[tblTransactions].[ShippingMethod],[dbo].[tblTransactions].[ReferencedTransactionGuid]
                        ,CT.UpdatedRowVersion 'CT_UpdatedRowVersion'
                        ,CT.UpdatedContext 'CT_UpdatedContext'
                        ,CT.UpdatedDate 'CT_UpdatedDate'
                    FROM [dbo].[tblTransactions]
                        INNER JOIN [track].[tblTransactions] CT
                            ON CT.PK_TransactionGuid = [dbo].[tblTransactions].[TransactionGuid] 
                    WHERE CT.PK_TransactionGuid = @TransactionGuid
            ) MERGE existingData
            USING (SELECT @TransID,@AliasName,@SubType,@Site,@TransReferenceID,@InventoryDate,@ShipToID,@ShipToCode,@SupplierID,@SupplierCode,@CreatedDate,@CreatedBy,@RequestedDeliveryDate,@UpdatedDate,@UpdatedBy,@TransDateTime,@TransVersion,@SCACCode,@CardNumber,@ShipmentNumber,@ShipperID,@ShipperCode,@OwnerID,@OwnerCode,@ManagerID,@ManagerCode,@CarrierID,@CarrierCode,@ConjoinTransID,@ReversedTransID,@LinkedDocumentNumber,@ReversalType,@PONumber,@TimeIn,@TimeOut,@TimeEnd,@RoutingID,@TicketSource,@LoadID,@BillToID,@BillToCode,@DriverIdentificationNumber,@CreditAmount,@CardExpiration,@CardName,@CardType,@CashAmount,@RouteOriginationDate,@InternationalRouteIndicator,@PreviousRoutingID,@ShippingDocumentNumber,@DocumentNumber,@STD,@ETD,@STA,@ETA,@SFT,@FST,@EstimatedFuelingDuration,@DeleteFlag,@TicketMode,@DestinationRegistrationID1,@DestinationSerialNumber1,@DestinationEquipmentType1,@DestinationEquipmentModel1,@DestinationCompanyEquipmentID1,@DestinationRegistrationID2,@DestinationSerialNumber2,@DestinationEquipmentType2,@DestinationEquipmentModel2,@DestinationCompanyEquipmentID2,@DestinationRegistrationID3,@DestinationSerialNumber3,@DestinationEquipmentType3,@DestinationEquipmentModel3,@DestinationCompanyEquipmentID3,@SourceRegistrationID1,@SourceSerialNumber1,@SourceEquipmentType1,@SourceEquipmentModel1,@SourceCompanyEquipmentID1,@SourceRegistrationID2,@SourceSerialNumber2,@SourceEquipmentType2,@SourceEquipmentModel2,@SourceCompanyEquipmentID2,@SourceRegistrationID3,@SourceSerialNumber3,@SourceEquipmentType3,@SourceEquipmentModel3,@SourceCompanyEquipmentID3,@OperatorID,@EffectiveDate,@ExpirationDate,@ScheduledDate,@AutoComplete,@Flag01,@Flag02,@Flag03,@Flag04,@Flag05,@Flag06,@Number01,@Number02,@Number03,@Number04,@Number05,@Number06,@ContactFirstName,@ContactSurname,@Date01,@Date02,@Date03,@Date04,@LegacyNumber,@Country,@ContactInfo,@AssociatedDocNumber,@AssociatedCLIN,@SubmittedToAccounting,@FuelCardID,@AssociatedTransportOrderNumber,@RequestedDateTime,@DispatchedD