                    ) AS remoteChanges ([TransID],[AliasName],[SubType],[Site],[TransReferenceID],[InventoryDate],[ShipToID],[ShipToCode],[SupplierID],[SupplierCode],[CreatedDate],[CreatedBy],[RequestedDeliveryDate],[UpdatedDate],[UpdatedBy],[TransDateTime],[TransVersion],[SCACCode],[CardNumber],[ShipmentNumber],[ShipperID],[ShipperCode],[OwnerID],[OwnerCode],[ManagerID],[ManagerCode],[CarrierID],[CarrierCode],[ConjoinTransID],[ReversedTransID],[LinkedDocumentNumber],[ReversalType],[PONumber],[TimeIn],[TimeOut],[TimeEnd],[RoutingID],[TicketSource],[LoadID],[BillToID],[BillToCode],[DriverIdentificationNumber],[CreditAmount],[CardExpiration],[CardName],[CardType],[CashAmount],[RouteOriginationDate],[InternationalRouteIndicator],[PreviousRoutingID],[ShippingDocumentNumber],[DocumentNumber],[STD],[ETD],[STA],[ETA],[SFT],[FST],[EstimatedFuelingDuration],[DeleteFlag],[TicketMode],[DestinationRegistrationID1],[DestinationSerialNumber1],[DestinationEquipmentType1],[DestinationEquipmentModel1],[DestinationCompanyEquipmentID1],[DestinationRegistrationID2],[DestinationSerialNumber2],[DestinationEquipmentType2],[DestinationEquipmentModel2],[DestinationCompanyEquipmentID2],[DestinationRegistrationID3],[DestinationSerialNumber3],[DestinationEquipmentType3],[DestinationEquipmentModel3],[DestinationCompanyEquipmentID3],[SourceRegistrationID1],[SourceSerialNumber1],[SourceEquipmentType1],[SourceEquipmentModel1],[SourceCompanyEquipmentID1],[SourceRegistrationID2],[SourceSerialNumber2],[SourceEquipmentType2],[SourceEquipmentModel2],[SourceCompanyEquipmentID2],[SourceRegistrationID3],[SourceSerialNumber3],[SourceEquipmentType3],[SourceEquipmentModel3],[SourceCompanyEquipmentID3],[OperatorID],[EffectiveDate],[ExpirationDate],[ScheduledDate],[AutoComplete],[Flag01],[Flag02],[Flag03],[Flag04],[Flag05],[Flag06],[Number01],[Number02],[Number03],[Number04],[Number05],[Number06],[ContactFirstName],[ContactSurname],[Date01],[Date02],[Date03],[Date04],[LegacyNumber],[Country],[ContactInfo],[AssociatedDocNumber],[AssociatedCLIN],[SubmittedToAccounting],[FuelCardID],[AssociatedTransportOrderNumber],[RequestedDateTime],[DispatchedDateTime],[ErrorFlag],[TransactionGuid],[SiteGuid],[LookupTransTypeIndex],[LookupTransactionStatusIndex],[LookupOriginApplicationIndex],[TransactionAliasGuid],[BillToCompanyGuid],[Destination1EquipmentGuid],[Destination2EquipmentGuid],[Destination3EquipmentGuid],[FinalStationIATAGuid],[FuelCardGuid],[ManagerCompanyGuid],[NextStationIATAGuid],[OperatorPersonnelGuid],[OriginStationIATAGuid],[OwnerCompanyGuid],[PreviousStationIATAGuid],[ShipperCompanyGuid],[ShipToCompanyGuid],[Source1EquipmentGuid],[Source2EquipmentGuid],[Source3EquipmentGuid],[SupplierCompanyGuid],[CarrierCompanyGuid],[ReasonCodeGuid],[OriginStationIATAID],[PreviousStationIATAID],[NextStationIATAID],[FinalStationIATAID],[OperatorName],[FuelAdditiveFlag],[IssuePoint],[IssuePointNumber],[RadioNumber],[GateID],[GateGuid],[ShippingMethod],[ReferencedTransactionGuid])
            ON (existingData.[TransactionGuid] = remoteChanges.[TransactionGuid])
            WHEN MATCHED AND (@sync_force_write = 1 
                            OR (existingData.CT_UpdatedRowVersion IS NULL) -- Record has never been changed.
                            OR (existingData.CT_UpdatedRowVersion IS NOT NULL AND existingData.CT_UpdatedRowVersion <= @sync_last_received_anchor_varbinary) -- it's been changed but not since our last sync session
                            OR (remoteChanges.UpdatedDate > existingData.CT_UpdatedDate AND (existingData.CT_UpdatedContext IS NULL OR existingData.CT_UpdatedContext <> @sync_client_id_binary)) -- incoming changes are newer than changes made locally or by another client via sync
                            OR (remoteChanges.UpdatedDate >= existingData.CT_UpdatedDate AND existingData.CT_UpdatedContext IS NOT NULL AND existingData.CT_UpdatedContext = @sync_client_id_binary)) -- IF THE CLIENT WAS THE LAST ONE THAT UPDATED IT, IT CAN REPLACE IT.
                THEN
                UPDATE SET [TransID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[TransID] ELSE remoteChanges.[TransID] END
                       ,[AliasName] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('AliasName'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[AliasName] ELSE remoteChanges.[AliasName] END
                       ,[SubType] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SubType'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[SubType] ELSE remoteChanges.[SubType] END
                       ,[Site] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Site'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[Site] ELSE remoteChanges.[Site] END
                       ,[TransReferenceID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransReferenceID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[TransReferenceID] ELSE remoteChanges.[TransReferenceID] END
                       ,[InventoryDate] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('InventoryDate'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[InventoryDate] ELSE remoteChanges.[InventoryDate] END
                       ,[ShipToID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipToID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ShipToID] ELSE remoteChanges.[ShipToID] END
                       ,[ShipToCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipToCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ShipToCode] ELSE remoteChanges.[ShipToCode] END
                       ,[SupplierID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SupplierID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[SupplierID] ELSE remoteChanges.[SupplierID] END
                       ,[SupplierCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SupplierCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[SupplierCode] ELSE remoteChanges.[SupplierCode] END
                       ,[CreatedDate] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CreatedDate'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[CreatedDate] ELSE remoteChanges.[CreatedDate] END
                       ,[CreatedBy] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CreatedBy'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[CreatedBy] ELSE remoteChanges.[CreatedBy] END
                       ,[RequestedDeliveryDate] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RequestedDeliveryDate'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[RequestedDeliveryDate] ELSE remoteChanges.[RequestedDeliveryDate] END
                       ,[UpdatedDate] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UpdatedDate'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[UpdatedDate] ELSE remoteChanges.[UpdatedDate] END
                       ,[UpdatedBy] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UpdatedBy'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[UpdatedBy] ELSE remoteChanges.[UpdatedBy] END
                       ,[TransDateTime] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransDateTime'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[TransDateTime] ELSE remoteChanges.[TransDateTime] END
                       ,[TransVersion] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransVersion'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[TransVersion] ELSE remoteChanges.[TransVersion] END
                       ,[SCACCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SCACCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[SCACCode] ELSE remoteChanges.[SCACCode] END
                       ,[CardNumber] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CardNumber'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[CardNumber] ELSE remoteChanges.[CardNumber] END
                       ,[ShipmentNumber] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipmentNumber'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ShipmentNumber] ELSE remoteChanges.[ShipmentNumber] END
                       ,[ShipperID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipperID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ShipperID] ELSE remoteChanges.[ShipperID] END
                       ,[ShipperCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipperCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ShipperCode] ELSE remoteChanges.[ShipperCode] END
                       ,[OwnerID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OwnerID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[OwnerID] ELSE remoteChanges.[OwnerID] END
                       ,[OwnerCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OwnerCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[OwnerCode] ELSE remoteChanges.[OwnerCode] END
                       ,[ManagerID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManagerID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ManagerID] ELSE remoteChanges.[ManagerID] END
                       ,[ManagerCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManagerCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ManagerCode] ELSE remoteChanges.[ManagerCode] END
                       ,[CarrierID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CarrierID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[CarrierID] ELSE remoteChanges.[CarrierID] END
                       ,[CarrierCode] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CarrierCode'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[CarrierCode] ELSE remoteChanges.[CarrierCode] END
                       ,[ConjoinTransID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ConjoinTransID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ConjoinTransID] ELSE remoteChanges.[ConjoinTransID] END
                       ,[ReversedTransID] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ReversedTransID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ReversedTransID] ELSE remoteChanges.[ReversedTransID] END
                       ,[LinkedDocumentNumber] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LinkedDocumentNumber'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[LinkedDocumentNumber] ELSE remoteChanges.[LinkedDocumentNumber] END
                       ,[ReversalType] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ReversalType'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN existingData.[ReversalType] ELSE remoteChanges.[ReversalType] END
